import{_ as t,C as e,o as n,c as s,j as i,E as r,a as l,a3 as d}from"./chunks/framework.C6R8kWFE.js";const k=JSON.parse(`{"title":"3-hafta","description":"","frontmatter":{"title":"3-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"11-sinf","link":"/11-sinf/"},"n":3,"bob":"I-bob · Dasturiy ta'minot ishlab chiqish asoslari","lessons":[{"g":7,"title":"Clean Code asoslari va SOLID: SRP hamda OCP tamoyillari","lead":"Professional kod madaniyati, to'g'ri nomlash, DRY/KISS/YAGNI tamoyillari hamda barqaror arxitektura poydevori: SRP va OCP.","link":"/11-sinf/hafta-03/dars-1","slide":"/slaydlar/11-sinf/hafta-03/dars-1.html","test":"/slaydlar/11-sinf/hafta-03/dars-1-test.html"},{"g":8,"title":"SOLID chuqurlashtirilgan: LSP, ISP, DIP va Code Smells refaktoringi","lead":"Liskov almashinish qoidasi, ixcham interfeyslar, Dependency Injection kuchi va yomon arxitektura alomatlarini (Code Smells) davolash.","link":"/11-sinf/hafta-03/dars-2","slide":"/slaydlar/11-sinf/hafta-03/dars-2.html","test":"/slaydlar/11-sinf/hafta-03/dars-2-test.html"},{"g":9,"title":"Loyihalash andozalari: Factory va Singleton arxitekturasi","lead":"Creational patterns: Factory Method yordamida obyekt yaratishni markazlashtirish, Singleton kuchi va global holat xatarlari.","link":"/11-sinf/hafta-03/dars-3","slide":"/slaydlar/11-sinf/hafta-03/dars-3.html","test":"/slaydlar/11-sinf/hafta-03/dars-3-test.html"}],"test":"/slaydlar/11-sinf/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"11-sinf/hafta-03/index.md","filePath":"11-sinf/hafta-03/index.md"}`),c={name:"11-sinf/hafta-03/index.md"},h={class:"blk"},u={id:"uyga-vazifa",tabindex:"-1"};function g(y,a,f,m,p,b){const o=e("Icon");return n(),s("div",null,[i("div",h,[i("h2",u,[r(o,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa. Parol, shaxsiy token, maxfiy kalit va shaxsiy ma&#39;lumotlarni repozitoriyga yozmang: topshirishda faqat ochiq GitHub repo yoki Pull Request havolasi kerak.</p><h3 id="_7-dars-uchun-clean-code-srp-va-ocp" tabindex="-1">7-dars uchun (Clean Code, SRP va OCP) <a class="header-anchor" href="#_7-dars-uchun-clean-code-srp-va-ocp" aria-label="Permalink to &quot;7-dars uchun (Clean Code, SRP va OCP)&quot;">​</a></h3><p><strong>1-topshiriq: «Kodni tozalash va OCP kengaytirish»</strong></p><ol><li>O&#39;z GitHub portfolio repozitoriyangizda yangi <code>refactor/clean-code</code> tarmog&#39;ini oching.</li><li><code>order_processor.py</code> nomli fayl yarating. Unga kamida 30 qatordan iborat «Spaghetti» kod (hisoblash, chegirma, soliq, xabar jo&#39;natish bitta funksiyada) yozing.</li><li>Ushbu kodni Clean Code qoidalari asosida tozalang: <ul><li>Funksiyalarni bo&#39;ling (<code>Extract Method</code>);</li><li>Mas&#39;uliyatlarni alohida sinflarga ajrating (<code>SRP</code>);</li><li><code>PaymentProcessor</code> abstrakt sinfi (<code>abc.ABC</code>) orqali to&#39;lov turlarini OCP talablariga moslang.</li></ul></li><li>O&#39;zgarishlarni semantik commitlar (<code>refactor(core): apply SRP and OCP to order processor</code>) bilan saqlab, GitHub&#39;ga push qiling.</li></ol><p><strong>Kutiladigan natija:</strong> tushunarli nomlangan, SRP va OCP tamoyillariga javob beradigan toza Python moduli.<br><strong>Topshirish:</strong> GitHub commit yoki fayl havolasi.</p><hr><h3 id="_8-dars-uchun-lsp-isp-dip-va-unit-test" tabindex="-1">8-dars uchun (LSP, ISP, DIP va Unit Test) <a class="header-anchor" href="#_8-dars-uchun-lsp-isp-dip-va-unit-test" aria-label="Permalink to &quot;8-dars uchun (LSP, ISP, DIP va Unit Test)&quot;">​</a></h3><p><strong>2-topshiriq: «Dependency Injection va Bazasiz Unit Test»</strong></p><ol><li><code>service_architecture.py</code> faylida <code>UserRepository</code> abstrakt interfeysini e&#39;lon qiling (<code>get_user(id)</code>, <code>save_user(user)</code>).</li><li>Ushbu interfeysga tayanuvchi <code>UserService</code> biznes mantiq sinfini yozing (Dependency Injection orqali repositoriyani qabul qilsin).</li><li>Testlar uchun xotirada ishlovchi <code>FakeUserRepository</code> (oddiy Python <code>dict</code> orqali) sinfini yozing.</li><li><code>test_user_service.py</code> faylida hech qanday PostgreSQL yoki tashqi serverga ulanmasdan <code>pytest</code> yoki oddiy <code>assert</code> orqali 3 ta test yozing (foydalanuvchi topilishi, yangi foydalanuvchi qo&#39;shilishi, topilmaganda xatolik).</li></ol><p><strong>Kutiladigan natija:</strong> DIP va DI tufayli 100% mustaqil, 0.01 soniyada yashil o&#39;tuvchi unit-testlar to&#39;plami.<br><strong>Topshirish:</strong> GitHub tarmog&#39;i va testlarning terminaldagi muvaffaqiyatli skrinshoti.</p><hr><h3 id="_9-dars-uchun-factory-va-singleton-andozalari" tabindex="-1">9-dars uchun (Factory va Singleton andozalari) <a class="header-anchor" href="#_9-dars-uchun-factory-va-singleton-andozalari" aria-label="Permalink to &quot;9-dars uchun (Factory va Singleton andozalari)&quot;">​</a></h3><p><strong>3-topshiriq: «Loyiha ConfigManager Singleton va Logger»</strong></p><ol><li><code>patterns.py</code> faylida <code>__new__</code> metodi yordamida <code>AppConfig</code> nomli Singleton sinfini tuzing. U dastur sozlamalarini (masalan: <code>APP_NAME</code>, <code>DEBUG</code>, <code>PORT</code>) faqat bir marta xotiraga yuklasin.</li><li>Ikkita alohida joyda <code>cfg1 = AppConfig()</code> va <code>cfg2 = AppConfig()</code> deb chaqirib, <code>cfg1 is cfg2</code> natijasi <code>True</code> ekanini <code>assert</code> bilan tasdiqlang.</li><li>Xabarnomalar tizimi uchun <code>NotificationFactory</code> yarating (<code>email</code>, <code>sms</code>, <code>telegram</code> turlari bo&#39;yicha mos obyektlarni qaytarsin). Noma&#39;lum tur kiritilganda <code>ValueError</code> tashlashini ta&#39;minlang.</li><li>Hammasini <code>main</code> tarmog&#39;iga Pull Request qilib yuboring.</li></ol><p><strong>Kutiladigan natija:</strong> Singleton va Factory andozalari to&#39;g&#39;ri tatbiq etilgan, to&#39;liq testlangan Python kodi.<br><strong>Topshirish:</strong> GitHub Pull Request havolasi.</p><hr>',16))])])}const P=t(c,[["render",g]]);export{k as __pageData,P as default};
